use serde_json::{Value, json};

pub fn solve(input: Value) -> Value {
    let intervals: Vec<(i64, i64)> = input.as_array().unwrap()
        .iter()
        .map(|v| (v[0].as_i64().unwrap(), v[1].as_i64().unwrap()))
        .collect();

    let mut merged: Vec<(i64, i64)> = Vec::new();
    let mut sorted_intervals = intervals.clone();
    sorted_intervals.sort_by_key(|&(start, _)| start);

    for (start, end) in sorted_intervals {
        if let Some(&(_, last_end)) = merged.last() {
            if start <= last_end {
                merged.last_mut().unwrap().1 = end.max(last_end);
            } else {
                merged.push((start, end));
            }
        } else {
            merged.push((start, end));
        }
    }

    if merged.len() < 2 {
        return json!(0);
    }

    let mut max_gap = 0;
    for i in 1..merged.len() {
        max_gap = max_gap.max(merged[i].0 - merged[i - 1].1 - 1);
    }

    json!(max_gap)
}
